function roleLabel(r){const x=String(r||'CITIZEN');return session?.preferredLanguage==='hi'?({CITIZEN:'नागरिक',ADMIN:'एडमिन',DEPARTMENT_HEAD:'विभाग प्रमुख',WORKER:'कर्मचारी',AUDITOR:'ऑडिटर'}[x]||x):session?.preferredLanguage==='mr'?({CITIZEN:'नागरिक',ADMIN:'अॅडमिन',DEPARTMENT_HEAD:'विभाग प्रमुख',WORKER:'कर्मचारी',AUDITOR:'ऑडिटर'}[x]||x):x}
function trStatic(value){const lang=session?.preferredLanguage||'en';if(lang==='en')return value;return uiText[lang]?.[value]||value}
function translateDom(root=document.body){if(!root||!session)return;const lang=session.preferredLanguage||'en';if(lang==='en')return;const dict=uiText[lang]||{};const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];let n;while(n=walker.nextNode()){if(n.parentElement?.closest('script,style,textarea'))continue;nodes.push(n)};nodes.forEach(node=>{const raw=node.nodeValue||'',trim=raw.trim();if(dict[trim])node.nodeValue=raw.replace(trim,dict[trim])});root.querySelectorAll('input,textarea,select,button,[title],[aria-label]').forEach(el=>{['placeholder','title','aria-label'].forEach(a=>{if(el.hasAttribute(a)){const v=el.getAttribute(a);if(dict[v])el.setAttribute(a,dict[v])}})});document.title=lang==='hi'?'SamadhanPoint — समस्याओं को समाधान में बदलना':lang==='mr'?'SamadhanPoint — समस्यांचे समाधान':'SamadhanPoint'}

function t(k){const l=session?.preferredLanguage||'en';return labels[l]?.[k]||labels.en[k]||k}
function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function toast(msg,alert=false){const tbox=$('#toast');tbox.textContent=msg;tbox.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>tbox.classList.remove('show'),3000);if(alert)showNotice(msg)}
function showNotice(msg){const old=$('.notice-alert');if(old)old.remove();const n=document.createElement('div');n.className='notice-alert';n.innerHTML=`<b>🔔 ${esc(t('notifications'))}</b><small>${esc(msg)}</small>`;document.body.appendChild(n);setTimeout(()=>n.remove(),5500)}
async function api(path,opt={}){const options={...opt,headers:{...(opt.headers||{})}};if(opt.body&&typeof opt.body!=='string'){options.headers['Content-Type']='application/json';options.body=JSON.stringify(opt.body)}if(session?.token)options.headers.Authorization='Bearer '+session.token;const r=await fetch(path,options);let j={};try{j=await r.json()}catch{}if(!r.ok)throw new Error(j.error||`Request failed (${r.status})`);return j}
function initials(name){return(name||'C').trim().split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase()}
function roleNav(){const r=session?.role||'CITIZEN';let n=[['dashboard','dashboard']];if(r==='CITIZEN')n.push(['complaints','complaints'],['new','new'],['track','track'],['triage','triage'],['appeals','appeals'],['notifications','notifications'],['help','Help & Support']);else if(r==='WORKER')n.push(['tasks','tasks'],['complaints','complaints'],['notifications','notifications']);else if(r==='AUDITOR')n.push(['complaints','complaints'],['analytics','analytics'],['evaluation','evaluation'],['appeals','appeals'],['notifications','notifications'],['audit','audit'],['reports','reports']);else if(r==='DEPARTMENT_HEAD')n.push(['complaints','complaints'],['analytics','analytics'],['tasks','tasks'],['appeals','appeals'],['notifications','notifications'],['reports','reports']);else if(r==='ADMIN')n.push(['complaints','complaints'],['analytics','analytics'],['wards','Ward Control'],['evaluation','evaluation'],['appeals','appeals'],['notifications','notifications'],['reports','reports'],['users','users'],['departments','departments'],['audit','audit']);n.push(['settings','settings']);return n}
function renderShell(){
 document.body.classList.remove('nav-open');
 $('#sideName').textContent=session?.name||trStatic('Citizen');$('#sideRole').textContent=roleLabel(session?.role);$('#crumbRole').textContent=roleLabel(session?.role);$('#avatar').textContent=initials(session?.name);$('#topAvatar').textContent=initials(session?.name);$('#langSelect').value=session?.preferredLanguage||'en';$('#pageTitle').textContent=pageTitle(currentPage);document.documentElement.lang=session?.preferredLanguage||'en';
 $('#nav').innerHTML=roleNav().map(([id,key])=>`<button class="navbtn ${currentPage===id?'active':''}" data-page="${id}"><span class="nav-icon">${navIcon[id]||'•'}</span><span>${esc(t(key))}</span>${id==='notifications'&&unreadCount?`<span class="nav-badge">${unreadCount>99?'99+':unreadCount}</span>`:''}</button>`).join('');
 $$('#nav .navbtn').forEach(b=>b.onclick=()=>navigate(b.dataset.page));updateBadge();
}
function pageTitle(p){const map={dashboard:'dashboard',complaints:'complaints',new:'new',track:'track',triage:'triage',analytics:'analytics',wards:'Ward Control',evaluation:'Evaluation',users:'users',audit:'audit',departments:'departments',appeals:'appeals',notifications:'notifications',tasks:'tasks',reports:'reports',settings:'settings',help:'Help & Support'};return t(map[p]||p)}
function updateBadge(){const b=$('#notificationBadge');if(!b)return;b.textContent=unreadCount>99?'99+':unreadCount;b.classList.toggle('hidden',!unreadCount)}
async function refreshUnread(showNew=false){if(!session?.token)return;try{const r=await api('/api/notifications/unread-count');unreadCount=Number(r.count||0);if(showNew&&unreadCount>lastUnread)showNotice(`${unreadCount-lastUnread} new notification(s) received.`);lastUnread=unreadCount;updateBadge();}catch{}}
function startNotificationPolling(){clearInterval(window.__notifPoll);if(!session)return;refreshUnread();window.__notifPoll=setInterval(()=>refreshUnread(true),12000)}
function navigate(page){currentPage=page;renderShell();renderPage(page)}
async function renderPage(page){const c=$('#content');c.innerHTML=`<div class="loading"><div class="spinner"></div><span>${esc(t('refresh'))}…</span></div>`;try{if(page==='dashboard')await renderDashboard(c);else if(page==='complaints'||page==='tasks')await renderComplaints(c,page==='tasks');else if(page==='new')renderNewComplaint(c);else if(page==='track')renderTrack(c);else if(page==='triage')renderTriage(c);else if(page==='analytics')await renderAnalytics(c);else if(page==='wards')await renderWards(c);else if(page==='evaluation')await renderEvaluation(c);else if(page==='appeals')await renderAppeals(c);else if(page==='users')await renderUsers(c);else if(page==='departments')await renderDepartments(c);else if(page==='audit')await renderAudit(c);else if(page==='notifications')await renderNotifications(c);else if(page==='reports')await renderReports(c);else if(page==='settings')renderSettings(c);else if(page==='help')renderHelp(c);else await renderDashboard(c)}catch(e){c.innerHTML=`<div class="panel"><div class="alert warn">${esc(e.message)}</div><button class="secondary" onclick="navigate('${page}')">↻ Retry</button></div>`}finally{setTimeout(()=>translateDom(c),0)}}
async function getAnalytics(){return(await api('/api/analytics')).data||{summary:{},departments:[],languages:[],wards:[],statuses:[],categories:[],priority:[],slaBuckets:[],trend:[],wardGeo:[]}}
function formatSla(seconds){
  seconds=Math.max(0,Number(seconds)||0);
  const d=Math.floor(seconds/86400),h=Math.floor((seconds%86400)/3600),m=Math.floor((seconds%3600)/60),s=seconds%60;
  const lang=session?.preferredLanguage||'en';const u=lang==='hi'?{d:'दि',h:'घं',m:'मि',s:'से'}:lang==='mr'?{d:'दि',h:'ता',m:'मि',s:'से'}:{d:'d',h:'h',m:'m',s:'s'};return d>0?`${d}${u.d} ${String(h).padStart(2,'0')}${u.h}`:h>0?`${h}${u.h} ${String(m).padStart(2,'0')}${u.m}`:`${String(m).padStart(2,'0')}${u.m} ${String(s).padStart(2,'0')}${u.s}`;
}
function slaBadge(g){
  const sla=g?.sla||{};
  const closed=['RESOLVED','COMPLETED','CLOSED'].includes(g?.status);
  if(closed)return sla.isBreached?`<span class="badge red">⚠ ${session?.preferredLanguage==='hi'?'SLA उल्लंघन • रुका':session?.preferredLanguage==='mr'?'SLA उल्लंघन • थांबले':'SLA BREACHED • stopped'}</span>`:`<span class="badge green">✓ ${session?.preferredLanguage==='hi'?'SLA पूरा • रुका':session?.preferredLanguage==='mr'?'SLA पूर्ण • थांबले':'SLA met • stopped'}</span>`;
  const sec=Number(sla.remainingSeconds ?? ((Number(sla.remainingMinutes)||0)*60));
  const cls=sla.isBreached?'red':sec<=3600?'red':sec<=21600?'orange':'green';
  const label=sla.isBreached?`⚠ ${session?.preferredLanguage==='hi'?'SLA उल्लंघन':session?.preferredLanguage==='mr'?'SLA उल्लंघन':'SLA BREACHED'}`:`⏰ SLA ${formatSla(sec)}`;
  return `<span class="badge ${cls} sla-clock" data-remaining-seconds="${sec}" data-breached="${sla.isBreached?'1':'0'}">${label}</span>`;
}
function startSlaCountdown(){
  clearInterval(window.__slaTicker);
  const tick=()=>{
    $$('.sla-clock').forEach(el=>{
      let sec=Math.max(0,Number(el.dataset.remainingSeconds||0));
      if(el.dataset.breached==='1'){el.textContent=`⚠ ${session?.preferredLanguage==='hi'?'SLA उल्लंघन':session?.preferredLanguage==='mr'?'SLA उल्लंघन':'SLA BREACHED'}`;return;}
      sec=Math.max(0,sec-1);el.dataset.remainingSeconds=String(sec);
      const cls=sec<=3600?'red':sec<=21600?'orange':'green';
      el.className=`badge ${cls} sla-clock`;
      el.textContent='⏰ SLA '+formatSla(sec);
      if(sec===0){el.dataset.breached='1';el.className='badge red sla-clock';el.textContent=`⚠ ${session?.preferredLanguage==='hi'?'SLA उल्लंघन':session?.preferredLanguage==='mr'?'SLA उल्लंघन':'SLA BREACHED'}`;}
    });
  };
  tick();window.__slaTicker=setInterval(tick,1000);
}
function showSlaAlerts(a){
  const breached=Number(a?.summary?.breached||0), critical=Number(a?.summary?.critical||0);
  if(breached>0 && session?.role!=='CITIZEN'){
    const key=`SP_SLA_ALERT_${session.id}_${new Date().toISOString().slice(0,10)}_${breached}`;
    if(!sessionStorage.getItem(key)){sessionStorage.setItem(key,'1');showNotice(`${breached} SLA breach${breached===1?'':'es'} require attention.`);}
  }
  return {breached,critical};
}
function wardHeat(items){
  if(!items?.length)return '<div class="empty"><div class="empty-icon">🗺</div><b>No ward data yet</b><p>Ward workload will appear as complaints are filed.</p></div>';
  const max=Math.max(...items.map(x=>Number(x.count)||0),1);
  return `<div class="ward-heat-grid">${items.slice(0,24).map(x=>{
    const n=Number(x.count)||0,b=Number(x.breached)||0;
    const intensity=Math.round(15+(n/max)*70);
    const cls=b>0?'ward-risk':'ward-ok';
    return `<div class="ward-cell ${cls}" style="--ward-intensity:${intensity}%"><b>${esc(x.label||'Unknown')}</b><strong>${n}</strong><small>${b?`⚠ ${b} breach${b===1?'':'es'}`:'No breach'}</small></div>`;
  }).join('')}</div>`;
}
function miniTrend(items){
  if(!items?.length)return '<div class="empty">No trend data.</div>';
  const max=Math.max(...items.map(x=>Number(x.count)||0),1);
  return `<div class="trend-chart">${items.map(x=>`<div class="trend-col"><b>${Number(x.count)||0}</b><i style="height:${Math.max(8,(Number(x.count)||0)*100/max)}%"></i><small>${esc(x.label)}</small></div>`).join('')}</div>`;
}

function statCard(icon,value,label){return`<div class="stat"><div class="icon">${icon}</div><b>${esc(value)}</b><span>${esc(label)}</span></div>`}
